const item = $input.first().json;
const body = item.body || item;
const headers = item.headers || {};
const authHeader = headers.authorization || headers.Authorization || '';

const rawDate = body.leave_date || body.leaveDate || '';
const fmt = (d) => {
  if (!d) return '';
  const pd = new Date(d);
  if (isNaN(pd)) return d;
  return pd.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

return [{ json: {
  token: authHeader.replace('Bearer ', ''),
  authHeader,
  leaveId: body.leaveId || body.leave_id || body.id || '',
  leave_date: rawDate,
  end_date: body.end_date || body.endDate || '',
  leaveDateDisplay: fmt(rawDate),
  endDateDisplay: fmt(body.end_date || body.endDate || ''),
  leave_days: parseInt(body.leave_days || body.leaveDays || 1),
  reason: body.reason || '',
  employee_name: body.employee_name || body.employeeName || body.name || '',
  employee_email: body.employee_email || body.employeeEmail || body.email || '',
  department: body.department || '',
  managerEmail: body.managerEmail || '',
  hrEmail: body.hrEmail || '',
  managerApprovalToken: body.managerApprovalToken || '',
  hrApprovalToken: body.hrApprovalToken || '',
  backendUrl:'http://backend:3001'
} }];

const managerResp = $('HTTP: Lookup Manager').first().json;
const hrResp = $('HTTP: Lookup HR').first().json;
const input = $('Parse Input').first().json;

const managerEmail = managerResp.email || input.managerEmail || '';
const hrEmail = hrResp.email || input.hrEmail || '';
const leaveDays = input.leave_days;
const needsHr = leaveDays > 3;

return [{ json: {
  ...input,
  managerEmail,
  hrEmail,
  needsHr,
  flowType: needsHr ? 'manager_then_hr' : 'manager_only'
} }];

